5	import org.springframework.samples.petclinic.model.Owner;
6	
7	/**
8	 * Derives an owner's membership points and the membership level those points map to,
9	 * from the owner's own fields.
10	 *
11	 * <p>Points start at 0 and accumulate: {@code +2} when an email address is present,
12	 * {@code +1} when the owner has no namesakes ({@code namesakeCount} is 0), {@code +2}
13	 * for a household of 3 or more, and {@code +3} for a tenure (registration date to today)
14	 * of more than one elapsed fiscal year (the fiscal year starts on 1 July).
15	 *
16	 * <p>Points map to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
17	 * 4 for 6 or more points.
18	 *
19	 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so
20	 * MapStruct does not mistake it for a generic mapping method and apply it to unrelated
21	 * fields; the mapper references it only through explicit expressions.
22	 */
23	public final class MembershipPointsDeriver {
24	
25	    private MembershipPointsDeriver() {
26	    }
27	
28	    /**
29	     * Returns the owner's membership points, derived from the owner's own fields.
30	     */
31	    public static int membershipPoints(Owner owner) {
32	        int points = 0;
33	        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
34	            points += 2;
35	        }
36	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
37	            points += 1;
38	        }
39	        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
40	            points += 2;
41	        }
42	        if (owner.getRegistrationDate() != null
43	            && FiscalYearDeriver.elapsedFiscalYears(owner.getRegistrationDate(), LocalDate.now()) > 1) {
44	            points += 3;
45	        }
46	        return points;
47	    }
