76	 */
77	
78	@RestController
79	@CrossOrigin(exposedHeaders = "errors, content-type")
80	@RequestMapping("/api")
81	public class OwnerRestControllerV1 implements OwnersApi {
82	
83	    /**
84	     * A pragmatic syntactic check for an email address: a non-empty local part, an {@code @},
85	     * and a dotted domain. Deliberately conservative so obviously malformed values (e.g. a bare
86	     * word with no {@code @}) are rejected while ordinary addresses are accepted.
87	     */
88	    private static final Pattern EMAIL_PATTERN =
89	        Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
90	
91	    /** Dedicated audit logger; carries owner lifecycle side-effects. */
92	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
93	
94	    /** Request header carrying the client-supplied idempotency key for creates. */
95	    private static final String IDEMPOTENCY_KEY_HEADER = "Idempotency-Key";
96	
97	    /**
98	     * Remembers the owner created for each already-seen {@code Idempotency-Key}, so a create that
99	     * repeats with the same key returns the originally created owner (200) instead of creating a
100	     * duplicate. Keyed by the raw header value; the mapped value is the created owner's id.
101	     */
102	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
103	
104	    private final ClinicService clinicService;
105	
106	    private final OwnerMapper ownerMapper;
107	
108	    private final PetMapper petMapper;
109	
110	    private final VisitMapper visitMapper;
111	
112	    public OwnerRestControllerV1(ClinicService clinicService,
113	                                 OwnerMapper ownerMapper,
114	                                 PetMapper petMapper,
115	                                 VisitMapper visitMapper) {
116	        this.clinicService = clinicService;
117	        this.ownerMapper = ownerMapper;
118	        this.petMapper = petMapper;
119	        this.visitMapper = visitMapper;
120	    }
121	
122	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
123	    @Override
124	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
125	        Collection<Owner> owners;
126	        if (lastName != null) {
127	            owners = this.clinicService.findOwnerByLastName(lastName);
128	        } else {
129	            owners = this.clinicService.findAllOwners();
130	        }
131	        if (owners.isEmpty()) {
132	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
133	        }
134	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
145	    }
146	
147	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
148	    @Override
149	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
150	        // Idempotent create: if this request repeats an already-seen 'Idempotency-Key', return the
151	        // owner created the first time (200) rather than creating a duplicate.
152	        String idempotencyKey = idempotencyKey();
153	        if (idempotencyKey != null) {
154	            Integer existingId = idempotentCreates.get(idempotencyKey);
155	            if (existingId != null) {
156	                Owner existing = this.clinicService.findOwnerById(existingId);
157	                if (existing != null) {
158	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
159	                }
160	            }
161	        }
162	        List<String> missingFields = new ArrayList<>();
163	        if (isBlank(ownerFieldsDto.getFirstName())) {
164	            missingFields.add("firstName");
165	        }
166	        if (isBlank(ownerFieldsDto.getLastName())) {
167	            missingFields.add("lastName");
168	        }
169	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
170	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
171	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
172	        // the owner's address sees the effective (structured-or-flat) value.
173	        applyAddress(ownerFieldsDto);
174	        if (isBlank(ownerFieldsDto.getAddress())) {
175	            missingFields.add("address");
176	        }
177	        if (isBlank(ownerFieldsDto.getCity())) {
178	            missingFields.add("city");
179	        }
180	        if (isBlank(ownerFieldsDto.getTelephone())) {
181	            missingFields.add("telephone");
182	        }
183	        if (!missingFields.isEmpty()) {
184	            throw new MissingOwnerFieldsException(missingFields);
185	        }
186	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
187	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
188	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
189	            throw new FutureRegistrationDateException(
190	                "registrationDate must not be later than the server date");
191	        }
192	        LocalDate registrationDate = toBusinessDay(
193	            suppliedRegistrationDate != null
194	                ? suppliedRegistrationDate
195	                : LocalDate.now());
196	        long registeredOnDay = this.clinicService.findAllOwners().stream()
197	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
198	            .count();
199	        if (registeredOnDay >= 100) {
200	            throw new DailyRegistrationLimitException(
201	                "100 or more owners have already been registered today");
202	        }
203	        boolean bulkSignupWarning = registeredOnDay > 80;
204	        String city = ownerFieldsDto.getCity();
205	        long ownersInCity = this.clinicService.findAllOwners().stream()
206	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
207	            .count();
208	        if (ownersInCity >= 50) {
209	            throw new CityAtCapacityException(
210	                "the owner's city already contains 50 or more owners");
211	        }
212	        String telephone = toE164(ownerFieldsDto.getTelephone());
213	        ownerFieldsDto.setTelephone(telephone);
214	        String email = normalizeEmail(ownerFieldsDto.getEmail());
215	        ownerFieldsDto.setEmail(email);
216	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
217	        String postcode = ownerFieldsDto.getPostcode();
218	        // Deterministic household id: owners with the same normalized last name and postcode
219	        // share it automatically, regardless of creation order. It is no longer created by the
220	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
221	        String householdId = householdId(lastName, postcode);
222	        // The household is keyed on (last name, postcode), so its existing members are the
223	        // existing owners with the same computed household id. Both the duplicate block and the
224	        // household size below key off this value.
225	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
226	            .filter(existing -> !existing.isDeleted())
227	            .filter(existing -> householdId.equals(
228	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
229	            .toList();
230	        // Household duplicate block: a second owner in an existing household is rejected as a
231	        // household duplicate (409) unless the request opts in via 'sharesHousehold'. Opting in
232	        // only bypasses this block; the owner is then created as a declared household member.
233	        if (!householdMembers.isEmpty()
234	            && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
235	            throw new DuplicateHouseholdException(
236	                "an owner with the same last name and postcode already exists");
237	        }
238	        // Single, consolidated duplicate check: reject only when the new owner's whole
239	        // derived identity key (telephone|email|householdId) equals an existing owner's.
240	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
241	        boolean identityInUse = this.clinicService.findAllOwners().stream()
242	            .filter(existing -> !existing.isDeleted())
243	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
244	                existing.getTelephone(), existing.getEmail(),
245	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
246	        if (identityInUse) {
247	            throw new DuplicateIdentityException(
248	                "an owner with the same identity key already exists");
249	        }
250	        HttpHeaders headers = new HttpHeaders();
251	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
252	        owner.setRegistrationDate(registrationDate);
253	        owner.setCustomerCode(deduplicateCustomerCode(
254	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
255	        owner.setHouseholdId(householdId);
256	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
257	        owner.setBulkSignupWarning(bulkSignupWarning);
258	        // Household size after this create: existing members plus the owner being created.
259	        owner.setHouseholdSize(householdMembers.size() + 1);
260	        // A declared household member is not a suspected duplicate, and no other create path
261	        // reaches here for a same-household owner, so a created owner is never flagged.
262	        owner.setPossibleDuplicate(false);
263	        owner.setPossibleDuplicateOf(null);
264	        owner.setDeleted(false);
265	        this.clinicService.saveOwner(owner);
266	        if (idempotencyKey != null) {
267	            idempotentCreates.put(idempotencyKey, owner.getId());
268	        }
269	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
270	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
271	            + "membershipNumber={}",
272	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
273	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
274	        headers.setLocation(UriComponentsBuilder.newInstance()
275	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
276	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
277	    }
278	
279	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
280	    @Override
281	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
282	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
283	        if (currentOwner == null) {
284	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
285	        }
286	        applyAddress(ownerFieldsDto);
287	        currentOwner.setAddress(ownerFieldsDto.getAddress());
288	        currentOwner.setAddressLine1(ownerFieldsDto.getAddressLine1());
289	        currentOwner.setAddressLine2(ownerFieldsDto.getAddressLine2());
290	        currentOwner.setCity(ownerFieldsDto.getCity());
291	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
292	        currentOwner.setLastName(ownerFieldsDto.getLastName());
293	        currentOwner.setTelephone(toE164(ownerFieldsDto.getTelephone()));
294	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
295	        this.clinicService.saveOwner(currentOwner);
296	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
297	    }
