377	    private static boolean isBlank(String value) {
378	        return value == null || value.isBlank();
379	    }
380	
381	    /**
382	     * Returns the {@code Idempotency-Key} header of the current request, or {@code null} when the
383	     * header is absent, blank, or there is no bound request. Read from the request context so the
384	     * generated {@link OwnersApi#addOwner} signature is left untouched.
385	     */
386	    private static String idempotencyKey() {
387	        if (!(RequestContextHolder.getRequestAttributes() instanceof ServletRequestAttributes attrs)) {
388	            return null;
389	        }
390	        String key = attrs.getRequest().getHeader(IDEMPOTENCY_KEY_HEADER);
391	        return isBlank(key) ? null : key;
392	    }
393	
394	    /**
395	     * The fixed public-holiday calendar. A registration date that lands on any of these dates is
396	     * rolled forward, just as a weekend is, to the next non-holiday business day.
397	     */
398	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
399	        LocalDate.of(2026, 1, 1),
400	        LocalDate.of(2026, 1, 26),
401	        LocalDate.of(2026, 4, 25),
402	        LocalDate.of(2026, 12, 25),
403	        LocalDate.of(2026, 12, 28));
404	
405	    /**
406	     * Rolls a registration date forward to the next business day: when it falls on a Saturday, a
407	     * Sunday or a listed public holiday it is advanced one day at a time until a non-holiday weekday
408	     * is reached; an unaffected weekday is returned unchanged. This is applied to the effective
409	     * registration date (whether supplied in the request or defaulted to the server date), so every
410	     * value derived from the registration date sees the adjusted business day.
411	     */
412	    private static LocalDate toBusinessDay(LocalDate date) {
413	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
414	                || date.getDayOfWeek() == DayOfWeek.SUNDAY
415	                || PUBLIC_HOLIDAYS.contains(date)) {
416	            date = date.plusDays(1);
417	        }
418	        return date;
419	    }
420	
421	    /**
422	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
423	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
424	     * lower-cased so that last names are compared case-insensitively.
425	     */
426	    private static String normalizeHousehold(String value) {
427	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
428	    }
429	
430	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
431	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
432	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
433	
434	    /**
435	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
436	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
437	     * upper-cased, and common street-type abbreviations are expanded token-by-token
438	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
439	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
440	     * used for every address comparison (household-duplicate detection and the shared household id).
441	     */
442	    private static String normalizeAddress(String value) {
443	        if (value == null) {
444	            return "";
445	        }
446	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
447	        if (collapsed.isEmpty()) {
448	            return "";
449	        }
450	        String[] tokens = collapsed.split(" ");
451	        StringBuilder sb = new StringBuilder();
452	        for (int i = 0; i < tokens.length; i++) {
453	            if (i > 0) {
454	                sb.append(' ');
455	            }
456	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
457	        }
458	        return sb.toString();
459	    }
460	
461	    /**
462	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
463	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
464	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
465	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
466	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
467	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
468	     * The resulting {@code address} is the effective value every address reader sees, and is blank
469	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
470	     */
471	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
472	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
473	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
474	        if (!isBlank(line1)) {
475	            ownerFieldsDto.setAddressLine1(line1);
476	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
477	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
478	        } else {
479	            ownerFieldsDto.setAddressLine1(null);
480	            ownerFieldsDto.setAddressLine2(null);
481	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
482	        }
483	    }
484	
485	    /**
486	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
487	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
488	     * deterministic function of the normalized last name and postcode, so every owner that shares
489	     * those values maps to the same identifier regardless of creation order. A {@code null}
490	     * postcode contributes the empty string.
491	     */
492	    private static String householdId(String normalizedLastName, String postcode) {
493	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
494	        return sha256Hex12(key);
495	    }
496	
497	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
498	    private static String sha256Hex12(String s) {
499	        try {
500	            byte[] digest = MessageDigest.getInstance("SHA-256")
501	                .digest(s.getBytes(StandardCharsets.UTF_8));
502	            StringBuilder sb = new StringBuilder(12);
503	            for (int i = 0; i < 6; i++) {
504	                sb.append(String.format("%02x", digest[i]));
505	            }
506	            return sb.toString();
507	        }
508	        catch (NoSuchAlgorithmException e) {
509	            throw new IllegalStateException("SHA-256 not available", e);
510	        }
511	    }
512	
513	    /**
514	     * Builds the {@code customerCode} assigned to a new owner, formatted
515	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
516	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
517	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
518	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
519	     * pure function of the owner's own identity fields.
520	     */
521	    private static String customerCode(String postcode, String telephone, String lastName) {
522	        String region = LocalityDeriver.region(postcode);
523	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
524	            + (lastName == null ? "" : lastName));
525	        return region + "-" + hash8;
526	    }
527	
528	    /**
529	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
530	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
531	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
532	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
533	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
534	     */
535	    private String deduplicateCustomerCode(String base) {
536	        Set<String> existing = this.clinicService.findAllOwners().stream()
537	            .map(Owner::getCustomerCode)
538	            .filter(code -> code != null)
539	            .collect(Collectors.toSet());
540	        if (!existing.contains(base)) {
541	            return base;
542	        }
543	        int n = 2;
544	        while (existing.contains(base + "-" + n)) {
545	            n++;
546	        }
547	        return base + "-" + n;
548	    }
549	
550	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
551	    private static String sha256Hex8(String s) {
552	        try {
553	            byte[] digest = MessageDigest.getInstance("SHA-256")
554	                .digest(s.getBytes(StandardCharsets.UTF_8));
555	            StringBuilder sb = new StringBuilder(8);
556	            for (int i = 0; i < 4; i++) {
557	                sb.append(String.format("%02X", digest[i]));
558	            }
559	            return sb.toString();
560	        }
561	        catch (NoSuchAlgorithmException e) {
562	            throw new IllegalStateException("SHA-256 not available", e);
563	        }
564	    }
565	
566	    /**
567	     * Counts the existing owners that share the given first name and last name, compared
568	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
569	     * owner currently being created is saved), so it reflects how many namesakes preceded the
570	     * new owner.
571	     */
572	    private int countNamesakes(String firstName, String lastName) {
573	        return (int) this.clinicService.findAllOwners().stream()
574	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
575	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
576	            .count();
577	    }
578	
579	    /**
580	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
581	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
582	     * national one, a single leading {@code '0'} is dropped, and the default country code
583	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
584	     * national number must have the length required by its country code ({@code '+61'} requires 9
585	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
586	     * raised (reported to the client as 400).
587	     */
588	    private static String toE164(String telephone) {
589	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
590	        String digits;
591	        if (cleaned.startsWith("+")) {
592	            digits = cleaned.substring(1);
593	        } else {
594	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
595	            digits = "61" + national;
596	        }
597	        if (!digits.matches("[0-9]{8,15}")) {
598	            throw new InvalidTelephoneException(
599	                "telephone must form a valid E.164 number with 8 to 15 digits");
600	        }
601	        validateNationalLength(digits);
602	        return "+" + digits;
603	    }
604	
605	    /** National-number length required for each supported country code (digits after the code). */
606	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
607	        "61", 9, "1", 10);
608	
609	    /**
610	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
611	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
612	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
613	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
614	     */
615	    private static void validateNationalLength(String digits) {
616	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
617	            String code = entry.getKey();
618	            if (digits.startsWith(code)) {
619	                int nationalLength = digits.length() - code.length();
620	                if (nationalLength != entry.getValue()) {
621	                    throw new InvalidTelephoneException(
622	                        "telephone national number must have " + entry.getValue()
623	                            + " digits for country code +" + code);
624	                }
625	                return;
626	            }
627	        }
628	    }
629	
630	    /**
631	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
632	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
633	     * any 4-digit postcode.
634	     */
635	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
636	        "NSW", new int[] {2000, 2099},
637	        "VIC", new int[] {3000, 3099},
638	        "QLD", new int[] {4000, 4099});
639	
640	    /**
641	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
642	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
643	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
644	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
645	     * no known region accepts any 4-digit postcode. A violation raises an
646	     * {@link InvalidPostcodeException} (reported to the client as 400).
647	     */
648	    private static void validatePostcode(String city, String postcode) {
649	        if (isBlank(postcode)) {
650	            return;
651	        }
652	        if (!postcode.matches("[0-9]{4}")) {
653	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
654	        }
655	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
656	        if (range == null) {
657	            return;
658	        }
659	        int value = Integer.parseInt(postcode);
660	        if (value < range[0] || value > range[1]) {
661	            throw new InvalidPostcodeException(
662	                "postcode is out of range for the owner's city region");
663	        }
664	    }
665	
666	    /**
667	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
668	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
669	     * check).
670	     */
671	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
672	        "mailinator.com", "tempmail.com", "guerrillamail.com");
673	
674	    /**
675	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
676	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
677	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
678	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
679	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
680	     * so it is stored and returned in canonical form.
681	     */
682	    private static String normalizeEmail(String email) {
683	        if (isBlank(email)) {
684	            return null;
685	        }
686	        String trimmed = email.trim();
687	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
688	            throw new InvalidEmailException("email must be a syntactically valid address");
689	        }
690	        String normalized = trimmed.toLowerCase(Locale.ROOT);
691	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
692	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
693	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
694	        }
695	        return normalized;
696	    }
697	}
