package org.springframework.samples.petclinic.mapper;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Derives an owner's membership points and the membership level those points map to,
 * from the owner's own fields.
 *
 * <p>Points start at 0 and accumulate: {@code +2} when an email address is present,
 * {@code +1} when the owner has no namesakes ({@code namesakeCount} is 0), {@code +2}
 * for a household of 3 or more, and {@code +3} for a tenure (registration date to today)
 * of more than one elapsed fiscal year (the fiscal year starts on 1 July).
 *
 * <p>Points map to a level: 1 for 0-1 points, 2 for 2-3 points, 3 for 4-5 points, and
 * 4 for 6 or more points.
 *
 * <p>Kept as a standalone helper (rather than a method on {@link OwnerMapper}) so
 * MapStruct does not mistake it for a generic mapping method and apply it to unrelated
 * fields; the mapper references it only through explicit expressions.
 */
public final class MembershipPointsDeriver {

    private MembershipPointsDeriver() {
    }

    /**
     * Returns the owner's membership points, derived from the owner's own fields.
     */
    public static int membershipPoints(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
            points += 1;
        }
        if (owner.getHouseholdSize() != null && owner.getHouseholdSize() >= 3) {
            points += 2;
        }
        if (owner.getRegistrationDate() != null
            && FiscalYearDeriver.elapsedFiscalYears(owner.getRegistrationDate(), LocalDate.now()) > 1) {
            points += 3;
        }
        return points;
    }

    /**
     * Returns the membership level for the given membership points: 1 for 0-1 points,
     * 2 for 2-3 points, 3 for 4-5 points, and 4 for 6 or more points.
     */
    public static int membershipLevel(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}

package org.springframework.samples.petclinic.mapper;

import org.jspecify.annotations.NonNull;
import org.mapstruct.Mapper;
import org.mapstruct.Mapping;
import org.springframework.data.domain.Page;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.rest.dto.OwnerDto;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.dto.OwnerPageDto;

import java.util.Collection;
import java.util.List;

/**
 * Maps Owner & OwnerDto using Mapstruct
 */
@Mapper(uses = PetMapper.class,
    imports = {LocalityDeriver.class, IdentityKeyDeriver.class, CheckDigitDeriver.class,
        AgeBandDeriver.class, TelephoneDisplayDeriver.class, MembershipPointsDeriver.class,
        FiscalYearDeriver.class})
public interface OwnerMapper {

    @Mapping(target = "selfLink",
        expression = "java(owner.getId() == null ? null : \"/api/owners/\" + owner.getId())")
    @Mapping(target = "displayName",
        expression = "java(owner.getLastName() + \", \" + owner.getFirstName())")
    @Mapping(target = "salutation",
        expression = "java((owner.getTitle() != null && !owner.getTitle().isBlank()) "
            + "? owner.getTitle() + \" \" + owner.getLastName() : owner.getLastName())")
    @Mapping(target = "initials",
        expression = "java(Character.toUpperCase(owner.getFirstName().charAt(0)) + \".\" "
            + "+ Character.toUpperCase(owner.getLastName().charAt(0)) + \".\")")
    @Mapping(target = "checkDigit",
        expression = "java(CheckDigitDeriver.checkDigit(owner.getCustomerCode()))")
    @Mapping(target = "membershipNumber",
        expression = "java(owner.getCustomerCode() + \"-M\" "
            + "+ String.format(\"%02d\", FiscalYearDeriver.fiscalYear("
            + "owner.getRegistrationDate()) % 100))")
    @Mapping(target = "fiscalYear",
        expression = "java(FiscalYearDeriver.fiscalYearLabel(owner.getRegistrationDate()))")
    @Mapping(target = "membershipPoints",
        expression = "java(MembershipPointsDeriver.membershipPoints(owner))")
    @Mapping(target = "membershipLevel",
        expression = "java(MembershipPointsDeriver.membershipLevel("
            + "MembershipPointsDeriver.membershipPoints(owner)))")
    @Mapping(target = "locality",
        expression = "java(LocalityDeriver.locality(owner.getCustomerCode()))")
    @Mapping(target = "timezone",
        expression = "java(LocalityDeriver.timezone("
            + "LocalityDeriver.locality(owner.getCustomerCode())))")
    @Mapping(target = "contactPreference",
        expression = "java((owner.getEmail() != null && !owner.getEmail().isBlank()) "
            + "? \"EMAIL\" : \"PHONE\")")
    @Mapping(target = "ageBand",
        expression = "java(AgeBandDeriver.ageBand(owner.getBirthDate(), "
            + "owner.getRegistrationDate()))")
    @Mapping(target = "identityKey",
        expression = "java(IdentityKeyDeriver.identityKey(owner.getTelephone(), "
            + "owner.getEmail(), owner.getHouseholdId()))")
    @Mapping(target = "telephoneDisplay",
        expression = "java(TelephoneDisplayDeriver.telephoneDisplay(owner.getTelephone()))")
    OwnerDto toOwnerDto(Owner owner);

    Owner toOwner(OwnerDto ownerDto);

    @Mapping(target = "id", ignore = true)
    @Mapping(target = "pets", ignore = true)
    Owner toOwner(OwnerFieldsDto ownerDto);

    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);

    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);

    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
        OwnerPageDto ownerPageDto = new OwnerPageDto();
        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
        ownerPageDto.setPage(ownerPage.getNumber());
        ownerPageDto.setSize(ownerPage.getSize());
        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
        return ownerPageDto;
    }
}

