    int maxMemberLevel = householdMembers.stream()
        .mapToInt(MembershipPointsDeriver::effectiveMembershipLevel)
        .max()
        .orElseThrow();
    cappedLevel = Math.min(naturalLevel, maxMemberLevel + 1);
}
owner.setMembershipLevel(cappedLevel);

